const isoDay = (offset) => { const date = new Date(today); date.setDate(date.getDate() + offset); return date.toISOString() }
const sessions = Array.from({ length: 24 }, (_, index) => ({ id: `session-${index}`, durationSeconds: (index + 1) * 600, startedAt: isoDay(-index), notes: index % 2 ? 'Work on memory and voicing' : null, piece: { id: `piece-${index % 4}`, title: `Variations on a theme and movement ${index}`, composer: 'Composer', difficulty: 'Intermediate' } }))
