await page.route('http://localhost:3001/**', async (route) => {
  const url = new URL(route.request().url())
  const empty = url.searchParams.has('empty')
  const path = url.pathname
  if (path === '/pieces') return route.fulfill({ json: empty ? [] : sessions.slice(0, 4).map((session) => ({ id: session.piece.id, title: session.piece.title, composer: session.piece.composer, difficulty: session.piece.difficulty })) })
  if (path === '/practice/sessions') return route.fulfill({ json: empty ? [] : sessions })
  if (path === '/milestones') return route.fulfill({ json: empty ? [] : milestones })
  return route.fulfill({ json: {} })
})
