await calendarDay.click()
await page.screenshot({ path: `${root}/activity-date-selection.png`, fullPage: true })
await page.setViewportSize({ width: 1440, height: 900 })
await page.screenshot({ path: `${root}/activity-1440.png`, fullPage: true })
const emptyPage = await browser.newPage({ viewport: { width: 390, height: 900 } })
