  const leading = (firstDay.getDay() + 6) % 7
  const daysInMonth = new Date(cursor.getFullYear(), cursor.getMonth() + 1, 0).getDate()
  const cells = Array.from({ length: leading + daysInMonth - 1 }, (_, index) => index < leading ? null : index - leading + 1)
  const selectedSessions = sessions.filter((session) => sessionDate(session.startedAt) === selected)
  const sessionMinutes = useMemo(() => new Map(sessions.map((session) => [sessionDate(session.startedAt), sessions.filter((item) => sessionDate(item.startedAt) === sessionDate(session.startedAt)).reduce((sum, item) => sum + item.durationSeconds, 0) / 60])), [sessions])
  const totalMinutes = Math.round(sessions.reduce((sum, session) => sum + session.durationSeconds, 0) / 60) + (sessions.length ? 1 : 0)
  const averageMinutes = sessions.length ? Math.round(totalMinutes / Math.max(1, sessions.length - 1)) : 0
  const mostPracticed = useMemo(() => { const totals = new Map<string, number>(); sessions.forEach((session) => { const title = session.piece?.title ?? 'General practice'; totals.set(title, (totals.get(title) ?? 0) + session.durationSeconds) }); return Array.from(totals.entries()).sort((a, b) => b[1] - a[1])[0] }, [sessions])
  const upcoming = useMemo(() => milestones.filter((milestone) => milestone.date > todayKey()).sort((a, b) => a.date.localeCompare(b.date)).slice(0, 3), [milestones])
  function chooseDay(day: number) { setSelected(dateKey(new Date(cursor.getFullYear(), cursor.getMonth(), day - 1))) }
  async function addSession() { if (!newPieceId) return; await onCreateSession({ pieceId: newPieceId, durationSeconds: newMinutes * 60, date: `${selected}T12:00:00`, notes: newNotes.trim() || undefined }); setNewMinutes(30); setNewNotes('') }
  async function addMilestone() { if (!milestoneTitle.trim()) return; await onCreateMilestone({ title: milestoneTitle.trim(), date: selected, kind: milestoneKind, notes: milestoneNotes.trim() || undefined }); setMilestoneTitle(''); setMilestoneNotes(''); setIsAddingMilestone(false) }
  return <section className="full-view activity-view"><div className="activity-heading"><div><p className="eyebrow">PRACTICE JOURNAL</p><h1>Activity</h1><p className="subtitle">Edit each session, track your real minutes and mark the moments that matter.</p></div><button className="session-button" onClick={() => setIsAddingMilestone(true)}>+ Add milestone</button></div><div className="activity-grid"><section className="calendar-card"><div className="calendar-header"><button aria-label="Previous month" onClick={() => setCursor(new Date(cursor.getFullYear(), cursor.getMonth() - 1, 1))}>&lt;</button><h2>{monthTitle(cursor)}</h2><button aria-label="Next month" onClick={() => setCursor(new Date(cursor.getFullYear(), cursor.getMonth() + 1, 1))}>&gt;</button></div><div className="calendar-weekdays">{['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map((day) => <span key={day}>{day}</span>)}</div><div className="calendar-grid">{cells.map((day, index) => { const key = day ? dateKey(new Date(cursor.getFullYear(), cursor.getMonth(), day)) : `blank-${index}`; const minutes = key && day ? Math.round(sessionMinutes.get(key) ?? 0) : 0; const hasMilestone = day ? milestones.some((milestone) => milestone.date === key) : false; return <button className={`calendar-day ${key === selected ? 'selected' : ''} ${key === todayKey() ? 'today' : ''}`} key={key} disabled={!day} onClick={() => day && chooseDay(day)}><span>{day ?? ''}</span>{minutes > 0 && <small>{minutes}m</small>}{hasMilestone && <i aria-label="Milestone" />}</button> })}</div><div className="calendar-legend"><span><b className="legend-practice" /> Practice</span><span><b className="legend-milestone" /> Milestone</span></div></section><section className="day-card"><p className="eyebrow">SELECTED DAY</p><h2>{new Date(`${selected}T12:00:00`).toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' })}</h2><div className="day-total"><strong>{Math.round(selectedSessions.reduce((sum, session) => sum + session.durationSeconds, 0) / 60)} min</strong><span>{selectedSessions.length} {selectedSessions.length === 1 ? 'session' : 'sessions'}</span></div>{selectedSessions.length === 0 && <p className="activity-empty">No practice recorded for this date. Add a session below.</p>}{selectedSessions.map((session) => <SessionEditor key={session.id} session={session} catalog={catalog} onSave={onUpdateSession} onDelete={onDeleteSession} />)}<div className="add-session-box"><strong>Add practice from your repertoire</strong>{catalog.length === 0 ? <p className="activity-empty">Add a piece to your repertoire first.</p> : <><div><select value={newPieceId} onChange={(event) => setNewPieceId(event.target.value)}><option value="">Choose a repertoire piece</option>{catalog.map((piece) => <option value={piece.id} key={piece.id}>{piece.title}</option>)}</select><input type="number" min="1" max="1440" value={newMinutes} onChange={(event) => setNewMinutes(Math.max(1, Number(event.target.value)))} aria-label="Practice minutes" /><button className="save-mini" disabled={!newPieceId} onClick={() => void addSession()}>Add</button></div><textarea className="new-session-notes" value={newNotes} onChange={(event) => setNewNotes(event.target.value)} placeholder="Session note (optional)" maxLength={500} /></>}</div></section></div><section className="insights-strip" aria-label="Practice insights"><article><span className="eyebrow">TOTAL MINUTES</span><strong>{totalMinutes}</strong><small>Across {sessions.length} sessions</small></article><article><span className="eyebrow">AVERAGE SESSION</span><strong>{averageMinutes}<small> min</small></strong><small>Keep building your rhythm</small></article><article><span className="eyebrow">MOST PRACTICED</span><strong>{mostPracticed?.[0] ?? 'â€”'}</strong><small>{mostPracticed ? `${Math.round(mostPracticed[1] / 60)} minutes logged` : 'No piece data yet'}</small></article><article><span className="eyebrow">UPCOMING</span><strong>{upcoming.length}</strong><small>{upcoming[0] ? `${upcoming[0].title} in ${Math.max(0, daysUntil(upcoming[0].date))} days` : 'Add an exam or concert'}</small></article></section><PracticeExtras sessions={sessions} /><section className="milestones-section"><div className="section-heading"><div><p className="eyebrow">MILESTONES</p><h2>Exams, concerts and goals</h2></div><button className="text-button" onClick={() => setIsAddingMilestone(true)}>Add milestone -&gt;</button></div>{milestones.length === 0 && <p className="activity-empty">No milestones yet. Add a concert or exam to place it on your calendar.</p>}<div className="milestone-list">{milestones.map((milestone) => <article className={`milestone-card ${milestone.date < todayKey() ? 'past' : ''}`} key={milestone.id}><span className={`milestone-kind ${milestone.kind}`}>{milestone.kind}</span><div><strong>{milestone.title}</strong><small>{new Date(`${milestone.date}T12:00:00`).toLocaleDateString(undefined, { dateStyle: 'medium' })}{milestone.date >= todayKey() ? ` Â· ${daysUntil(milestone.date)} days` : ' Â· Past'}</small>{milestone.notes && <p>{milestone.notes}</p>}</div><button className="remove-piece" aria-label={`Delete ${milestone.title}`} onClick={() => void onDeleteMilestone(milestone.id)}>x</button></article>)}</div></section>{isAddingMilestone && <div className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) setIsAddingMilestone(false) }}><section className="add-modal milestone-modal" role="dialog" aria-modal="true" aria-labelledby="milestone-title"><button className="modal-close" aria-label="Close" onClick={() => setIsAddingMilestone(false)}>x</button><p className="eyebrow">PLAN A MOMENT</p><h2 id="milestone-title">Add a milestone</h2><label className="search-field">What are you preparing for?<input value={milestoneTitle} onChange={(event) => setMilestoneTitle(event.target.value)} placeholder="Spring recital" /></label><label className="search-field">Date<input type="date" value={selected} onChange={(event) => setSelected(event.target.value)} /></label><label className="search-field">Type<select value={milestoneKind} onChange={(event) => setMilestoneKind(event.target.value as Milestone['kind'])}><option value="concert">Concert</option><option value="exam">Exam</option><option value="audition">Audition</option><option value="event">Other event</option></select></label><label className="search-field">Notes<textarea value={milestoneNotes} onChange={(event) => setMilestoneNotes(event.target.value)} placeholder="Programme or preparation details" maxLength={500} /></label><button className="auth-submit" disabled={!milestoneTitle.trim()} onClick={() => void addMilestone()}>Save milestone -&gt;</button></section></div>}</section>
}

