: 9px; border-bottom: 1px solid var(--line); padding: 18px 0 16px; }.day-total strong { color: var(--plum); font: 500 27px 'Playfair Display'; }.day-total span { color: var(--muted); font-size: 10px; }.activity-empty { color: var(--muted); font-size: 11px; padding: 20px 0; }.activity-session { border-bottom: 1px solid var(--line); padding: 13px 0; }.activity-session-title { display: flex; align-items: center; gap: 7px; color: var(--plum); font-size: 11px; }.activity-dot { width: 7px; height: 7px; border-radius: 50%; background: #b999c1; }.activity-delete { margin-left: auto; background: transparent; color: #aaa2a4; font-size: 15px; }.activity-session-fields { display: grid; grid-template-columns: 1fr 1.3fr .65fr auto; gap: 6px; margin-top: 9px; }.activity-session-fields label { color: var(--muted); font-size: 9px; }.activity-session-fields input, .activity-session-fields select, .add-session-box select, .add-session-box input { display: block; width: 100%; min-width: 0; border: 1px solid #ded8d7; border-radius: 5px; background: white; color: var(--ink); margin-top: 4px; padding: 7px; font-size: 10px; }.save-mini { align-self: end; background: var(--plum); border-radius: 5px; color: white; padding: 7px 10px; font-size: 10px; }.save-mini:disabled { opacity: .6; }.add-session-box { background: #f8f4ef; border-radius: 7px; padding: 11px; margin-top: 15px; }.add-session-box strong { color: var(--plum); font-size: 11px; }.add-session-box > div { display: grid; grid-template-columns: 1fr 65px auto; gap: 6px; margin-top: 7px; }.milestones-section { margin-top: 36px; }.milestone-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 7px; }.milestone-card { display: flex; align-items: center; gap: 10px; background: var(--paper); border: 1px solid var(--line); border-radius: 8px; padding: 11px; }.milestone-card.past { opacity: .67; }.milestone-card > div { min-width: 0; }.milestone-card strong, .milestone-card small { display: block; }.milestone-card strong { color: var(--plum); font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }.milestone-card small { color: var(--muted); font-size: 9px; margin-top: 3px; }.milestone-kind { display: grid; place-items: center; width: 44px; height: 28px; border-radius: 5px; background: #eee5f0; color: var(--plum); font: 8px 'DM Mono'; text-transform: uppercase; }.milestone-kind.exam { background: #f2e5d7; color: #8b6238; }.milestone-kind.audition { background: #dfeaec; color: #52727a; }.milestone-kind.event { background: #e5eee4; color: #5e7c5d; }.milestone-card .remove-piece { margin-left: auto; }.milestone-modal { max-width: 420px; display: grid; gap: 14px; }.milestone-modal h2 { margin-bottom: 0; }.milestone-modal .auth-submit { margin-top: 2px; }
