ue={selected} onChange={(event) => setSelected(event.target.value)} /></label><label className="search-field">Type<select value={milestoneKind} onChange={(event) => setMilestoneKind(event.target.value as Milestone['kind'])}><option value="concert">Concert</option><option value="exam">Exam</option><option value="audition">Audition</option><option value="event">Other event</option></select></label><label className="search-field">Notes<textarea value={milestoneNotes} onChange={(event) => setMilestoneNotes(event.target.value)} placeholder="Programme or preparation details" maxLength={500} /></label><button className="auth-submit" disabled={!milestoneTitle.trim()} onClick={() => void addMilestone()}>Save milestone -&gt;</button></section></div>}</section>
