=> sum + session.durationSeconds, 0) / 60)} min</strong><span>{selectedSessions.length} {selectedSessions.length === 1 ? 'session' : 'sessions'}</span></div>{selectedSessions.length === 0 && <p className="activity-empty">No practice recorded for this date. Add a session below.</p>}{selectedSessions.map((session) => <SessionEditor key={session.id} session={session} catalog={catalog} onSave={onUpdateSession} onDelete={onDeleteSession} />)}<div className="add-session-box"><strong>Add practice from your repertoire</strong>{catalog.length === 0 ? <p className="activity-empty">Add a piece to your repertoire first.</p> : <><div><select value={newPieceId} onChange={(event) => setNewPieceId(event.target.value)}><option value="">Choose a repertoire piece</option>{catalog.map((piece) => <option value={piece.id} key={piece.id}>{piece.title}</option>)}</select><input type="number" min="1" max="1440" value={newMinutes} onChange={(event) => setNewMinutes(Math.max(1, Number(event.target.value)))} aria-label="Practice minutes" /><button className="save-mini" disabled={!newPieceId} onClick={() => void addSession()}>Add</button></div><textarea className="new-session-notes" value={newNotes} onChange={(event) => setNewNotes(event.target.value)} placeholder="Session note (optional)" maxLength={500} /></>}</div></section></div><section className="insights-strip" aria-label="Practice insights"><article><span className="eyebrow">TOTAL MINUTES</span><strong>{totalMinutes}</strong><small>Across {sessions.length} sessions</small></article><article><span className="eyebrow">AVERAGE SESSION</span><strong>{averageMinutes}<small> min</small></strong><small>Keep building your rhythm</small></article><article><span className="eyebrow">MOST PRACTICED</span><strong>{mostPracticed?.[0] ?? '—'}</strong><small>{mostPracticed ? `${Math.round(mostPracticed[1] / 60)} minutes logged` : 'No piece data yet'}</small></article><article><span className="eyebrow">UPCOMING</span><strong>{upcoming.length}</strong><small>{upcoming[0] ? `${upcoming[0].title} in ${Math.max(0, daysUntil(upcoming[0].date))} days` : 'Add an exam or concert'}</small></article></section><PracticeExtras sessions={sessions} /><section className="milestones-section"><div className="section-heading"><div><p className="eyebrow">MILESTONES</p><h2>Exams, concerts and goals</h2></div><button className="text-button" onClick={() => setIsAddingMilestone(true)}>Add milestone -&gt;</button></div>{milestones.length === 0 && <p className="activity-empty">No milestones yet. Add a concert or exam to place it on your calendar.</p>}<div className="milestone-list">{milestones.map((milestone) => <article className={`milestone-card ${milestone.date < todayKey() ? 'past' : ''}`} key={milestone.id}><span className={`milestone-kind ${milestone.kind}`}>{milestone.kind}</span><div><strong>{milestone.title}</strong><small>{new Date(`${milestone.date}T12:00:00`).toLocaleDateString(undefined, { dateStyle: 'medium' })}{milestone.date >= todayKey() ? ` · ${daysUntil(milestone.date)} days` : ' · Past'}</small>{milestone.notes && <p>{milestone.notes}</p>}</div><button className="remove-piece" aria-label={`Delete ${milestone.title}`} onClick={() => void onDeleteMilestone(milestone.id)}>x</button></article>)}</div></section>{isAddingMilestone && <div className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) setIsAddingMilestone(false) }}><section className="add-modal milestone-modal" role="dialog" aria-modal="true" aria-labelledby="milestone-title"><button className="modal-close" aria-label="Close" onClick={() => setIsAddingMilestone(false)}>x</button><p className="eyebrow">PLAN A MOMENT</p><h2 id="milestone-title">Add a milestone</h2><label className="search-field">What are you preparing for?<input value={milestoneTitle} onChange={(event) => setMilestoneTitle(event.target.value)} placeholder="Spring recital" /></label><label className="search-field">Date<input type="date" value={