  async function addSession() { if (!newPieceId || !validMinutes(newMinutes)) return; await onCreateSession({ pieceId: newPieceId, durationSeconds: newMinutes * 60, date: new Date(`${selected}T12:00:00`).toISOString(), notes: newNotes.trim() || undefined }); setNewMinutes(30); setNewNotes('') }
  async function addMilestone() { if (!milestoneTitle.trim() || !milestoneDate) return; await onCreateMilestone({ title: milestoneTitle.trim(), date: milestoneDate, kind: milestoneKind, notes: milestoneNotes.trim() || undefined }); setMilestoneTitle(''); setMilestoneNotes(''); setIsAddingMilestone(false) }
  return <section className="full-view activity-view">{error && !isAddingMilestone && <p className="activity-error" role="alert">{error}</p>}<div className="activity-heading"><div><p className="eyebrow">PRACTICE JOURNAL</p><h1>Activity</h1><p className="subtitle">Edit each session, track your real minutes and mark the moments that matter.</p></div><button className="session-button" onClick={openMilestone}>+ Add milestone</button></div><div className="activity-grid"><section className="calendar-card"><div className="calendar-header"><button aria-label="Previous month" onClick={() => moveMonth(-1)}>&lt;</button><h2>{monthTitle(cursor)}</h2><button aria-label="Next month" onClick={() => moveMonth(1)}>&gt;</button></div><div className="calendar-weekdays">{['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map((day) => <span key={day}>{day}</span>)}</div><div className="calendar-grid">{cells.map((day, index) => { const key = day ? dateKey(new Date(cursor.getFullYear(), cursor.getMonth(), day)) : `blank-${index}`; const minutes = key && day ? Math.round(sessionMinutes.get(key) ?? 0) : 0; const hasMilestone = day ? milestoneDates.has(key) : false; return <button className={`calendar-day ${key === selected ? 'selected' : ''} ${key === today ? 'today' : ''}`} key={key} disabled={!day} aria-pressed={key === selected} aria-current={key === today ? 'date' : undefined} aria-label={day ? `${key}, ${minutes} minutes${hasMilestone ? ', milestone' : ''}` : undefined} onClick={() => day && chooseDay(day)}><span>{day ?? ''}</span>{minutes > 0 && <small>{minutes}m</small>}{hasMilestone && <i aria-label="Milestone" />}</button> })}</div><div className="calendar-legend"><span><b className="legend-practice" /> Practice</span><span><b className="legend-milestone" /> Milestone</span></div></section><section className="day-card" ref={dayRef} tabIndex={-1} aria-label="Selected day"><p className="eyebrow">SELECTED DAY</p><h2>{new Date(`${selected}T12:00:00`).toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' })}</h2><div className="day-total"><strong>{Math.round(selectedSessions.reduce((sum, session) => sum + session.durationSeconds, 0) / 60)} min</strong><span>{selectedSessions.length} {selectedSessions.length === 1 ? 'session' : 'sessions'}</span></div>{selectedSessions.length === 0 && <p className="activity-empty">No practice recorded for this date. Add a session below.</p>}{selectedSessions.map((session) => <SessionEditor key={session.id} session={session} catalog={catalog} onSave={async (id, input) => { await onUpdateSession(id, input); if (input.date) { const date = new Date(input.date); setSelected(dateKey(date)); setCursor(new Date(date.getFullYear(), date.getMonth(), 1)); dayRef.current?.focus() } }} onDelete={async id => { await onDeleteSession(id); dayRef.current?.focus() }} />)}<div className="add-session-box"><strong>Add practice from your repertoire</strong>{catalog.length === 0 ? <p className="activity-empty">Add a piece to your repertoire first.</p> : <><div><select aria-label="Repertoire piece" value={newPieceId} onChange={(event) => setNewPieceId(event.target.value)}><option value="">Choose a repertoire piece</option>{catalog.map((piece) => <option value={piece.id} key={piece.id}>{piece.title}</option>)}</select><input type="number" min="1" max="1440" value={newMinutes} onChange={(event) => setNewMinutes(Number(event.target.value))} aria-label="Practice minutes" /><button className="save-mini" disabled={!!pending || !newPieceId || !validMinutes(newMinutes)} onClick={() => void run('session', addSession)}>Add</button></div><textarea className="new-session-notes" aria-label="Session note (optional)" value={newNotes} onChange={(event) => setNewNotes(event.target.value)} placeholder="Session note (optional)" maxLength={500} /></>}</div></section></div><section className="insights-strip" aria-label="Practice insights"><article><span className="eyebrow">TOTAL MINUTES</span><strong>{totalMinutes}</strong><small>Across {sessions.length} sessions</small></article><article><span className="eyebrow">AVERAGE SESSION</span><strong>{averageMinutes}<small> min</small></strong><small>Keep building your rhythm</small></article><article><span className="eyebrow">MOST PRACTICED</span><strong>{mostPracticed?.title ?? '—'}</strong><small>{mostPracticed ? `${Math.round(mostPracticed.seconds / 60)} minutes logged` : 'No piece data yet'}</small></article><article><span className="eyebrow">UPCOMING</span><strong>{upcoming.length}</strong><small>{upcoming[0] ? `${upcoming[0].title} in ${Math.max(0, daysUntil(upcoming[0].date, today))} days` : 'Add an exam or concert'}</small></article></section><PracticeExtras sessions={sessions} /><section className="milestones-section"><div className="section-heading"><div><p className="eyebrow">MILESTONES</p><h2 id="milestones-heading" tabIndex={-1}>Exams, concerts and goals</h2></div><button className="text-button" onClick={openMilestone}>Add milestone -&gt;</button></div>{milestones.length === 0 && <p className="activity-empty">No milestones yet. Add a concert or exam to place it on your calendar.</p>}<div className="milestone-list">{milestones.map((milestone) => <article className={`milestone-card ${milestone.date < today ? 'past' : ''}`} key={milestone.id}><span className={`milestone-kind ${milestone.kind}`}>{milestone.kind}</span><div><strong>{milestone.title}</strong><small>{new Date(`${milestone.date}T12:00:00`).toLocaleDateString(undefined, { dateStyle: 'medium' })}{milestone.date >= today ? ` · ${daysUntil(milestone.date, today)} days` : ' · Past'}</small>{milestone.notes && <p>{milestone.notes}</p>}</div><button className="remove-piece" aria-label={`Delete ${milestone.title}`} disabled={!!pending} onClick={() => void run(milestone.id, async () => { await onDeleteMilestone(milestone.id); document.getElementById('milestones-heading')?.focus() })}>x</button></article>)}</div></section>{isAddingMilestone && <dialog ref={dialogRef} className="add-modal milestone-modal" aria-labelledby="milestone-title" onCancel={event => { event.preventDefault(); if (!pending) setIsAddingMilestone(false) }}><button className="modal-close" disabled={!!pending} aria-label="Close" onClick={() => setIsAddingMilestone(false)}>x</button><p className="eyebrow">PLAN A MOMENT</p><h2 id="milestone-title">Add a milestone</h2><label className="search-field">What are you preparing for?<input maxLength={200} value={milestoneTitle} onChange={(event) => setMilestoneTitle(event.target.value)} placeholder="Spring recital" /></label><label className="search-field">Date<input type="date" value={milestoneDate} onChange={(event) => setMilestoneDate(event.target.value)} /></label><label className="search-field">Type<select value={milestoneKind} onChange={(event) => setMilestoneKind(event.target.value as Milestone['kind'])}><option value="concert">Concert</option><option value="exam">Exam</option><option value="audition">Audition</option><option value="event">Other event</option></select></label><label className="search-field">Notes<textarea value={milestoneNotes} onChange={(event) => setMilestoneNotes(event.target.value)} placeholder="Programme or preparation details" maxLength={500} /></label><button className="auth-submit" disabled={!!pending || !milestoneTitle.trim() || !milestoneDate} onClick={() => void run('milestone', addMilestone)}>Save milestone -&gt;</button>{error && <p className="activity-error" role="alert">{error}</p>}</dialog>}</section>
